B.a_p=new A.hs("\ub458 \ub2e4 \ucc28\ub97c \uc774\uc6a9\ud558\uace0, \uc57d\uc815\ud55c \ub3c8\uc744 \ub0b4\uc694","\uc7a5\uae30\ub80c\ud2b8\ub294 \ub80c\ud130\uce74 \ud68c\uc0ac\uc758 \ucc28\ub97c, \ub9ac\uc2a4\ub294 \uae08\uc735\uc0ac\uc758 \ucc28\ub97c \uacc4\uc57d \uae30\uac04 \ub3d9\uc548 \uc774\uc6a9\ud558\ub294 \ubc29\uc2dd\uc774\uc5d0\uc694. \uc6d4 \uae08\uc561\ub9cc \ub098\ub780\ud788 \ubcf4\uae30\ubcf4\ub2e4 \ubcf4\ud5d8\xb7\uc138\uae08\xb7\uc815\ube44\uac00 \uc5b4\ub514\uae4c\uc9c0 \ud3ec\ud568\ub410\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud558\uc138\uc694.","\uac19\uc740 \ucc28\uc778\ub370, \ub80c\ud2b8\uc640 \ub9ac\uc2a4\ub294 \ubb50\uac00 \ub2e4\ub97c\uae4c?","\ucc28\ub7c9\uc744 \uc774\uc6a9\ud558\ub294 \ubc29\uc2dd\uacfc \uc6d4 \uae08\uc561\uc5d0 \ud3ec\ud568\ub41c \ud56d\ubaa9\uc744 \uba3c\uc800 \ube44\uad50\ud574\uc694.")
B.a_f=new A.hs("\uc7a5\uae30\ub80c\ud2b8\ub294 \ubcf4\ud5d8\uacfc \uc138\uae08\uc744 \ud568\uaed8 \ubd10\uc694","\ubcf4\ud1b5 \uc790\ub3d9\ucc28\ubcf4\ud5d8\ub8cc\uc640 \uc790\ub3d9\ucc28\uc138\uac00 \uc6d4 \ub300\uc5ec\ub8cc\uc5d0 \ud3ec\ud568\ub3fc\uc694. \ubc88\ud638\ud310\uc740 \ud558\xb7\ud5c8\xb7\ud638\ub97c \uc0ac\uc6a9\ud574\uc694. \ub2e4\ub9cc \uc815\ube44 \uc11c\ube44\uc2a4\uc640 \uc18c\ubaa8\ud488 \uad50\uccb4\uae4c\uc9c0 \ubaa8\ub450 \ud3ec\ud568\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5b4\uc11c \uacc4\uc57d\ubcc4 \uc81c\uacf5 \ubc94\uc704\ub97c \ud655\uc778\ud574\uc57c \ud574\uc694.","\ub80c\ud2b8\ub294 \ubcf4\ud5d8\uacfc \uc790\ub3d9\ucc28\uc138\uac00 \uc6d4 \ub300\uc5ec\ub8cc\uc5d0 \ub4e4\uc5b4 \uc788\uad6c\ub098.","\uc815\ube44\ub098 \uc18c\ubaa8\ud488\uae4c\uc9c0 \ubaa8\ub450 \ud3ec\ud568\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694.")
